def max_value_of_permutation(N):
    if N == 1:
        return 0
    if N % 2 == 0:
        return N * (N - 1) + (N // 2) - 1
    else:
        return N * (N - 1) + (N // 2)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    results = []
    for i in range(1, T + 1):
        N = int(data[i])
        results.append(max_value_of_permutation(N))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
